CREATE TABLE IF NOT EXISTS reg_kpi_results ( id TEXT PRIMARY KEY, kpi_key TEXT NOT NULL, period TEXT NOT NULL, subject TEXT NOT NULL DEFAULT '', numerator REAL, denominator REAL, value REAL NOT NULL, source_ref TEXT NOT NULL CHECK (length(source_ref) > 0), note TEXT, created_by TEXT NOT NULL REFERENCES users(id), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, voided_at TEXT, voided_by TEXT REFERENCES users(id), void_reason TEXT );
CREATE UNIQUE INDEX IF NOT EXISTS reg_kpi_results_active_idx ON reg_kpi_results(kpi_key, period, subject) WHERE voided_at IS NULL;
CREATE TABLE IF NOT EXISTS reg_kpi_targets ( id INTEGER PRIMARY KEY AUTOINCREMENT, kpi_key TEXT NOT NULL, target_value REAL NOT NULL, basis_ref TEXT NOT NULL CHECK (length(basis_ref) > 0), set_by TEXT NOT NULL REFERENCES users(id), set_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP );
CREATE INDEX IF NOT EXISTS reg_kpi_targets_key_idx ON reg_kpi_targets(kpi_key, id);
CREATE TRIGGER IF NOT EXISTS reg_kpi_results_no_delete BEFORE DELETE ON reg_kpi_results BEGIN SELECT RAISE(ABORT, 'LOCKED: KPI results cannot be deleted, void them instead'); END;
CREATE TRIGGER IF NOT EXISTS reg_kpi_results_frozen BEFORE UPDATE ON reg_kpi_results WHEN OLD.voided_at IS NOT NULL OR NEW.voided_at IS NULL OR NEW.id IS NOT OLD.id OR NEW.kpi_key IS NOT OLD.kpi_key OR NEW.period IS NOT OLD.period OR NEW.subject IS NOT OLD.subject OR NEW.numerator IS NOT OLD.numerator OR NEW.denominator IS NOT OLD.denominator OR NEW.value IS NOT OLD.value OR NEW.source_ref IS NOT OLD.source_ref OR NEW.note IS NOT OLD.note OR NEW.created_by IS NOT OLD.created_by OR NEW.created_at IS NOT OLD.created_at BEGIN SELECT RAISE(ABORT, 'LOCKED: KPI result cannot be edited, void it and record a new one'); END;
CREATE TRIGGER IF NOT EXISTS reg_kpi_targets_no_update BEFORE UPDATE ON reg_kpi_targets BEGIN SELECT RAISE(ABORT, 'LOCKED: KPI target history is append-only'); END;
CREATE TRIGGER IF NOT EXISTS reg_kpi_targets_no_delete BEFORE DELETE ON reg_kpi_targets BEGIN SELECT RAISE(ABORT, 'LOCKED: KPI target history is append-only'); END;
